// === Tab: Particle ===
class Particle {

	// I've used an object argument with defaults for the inputs
	// to avoid argument ordering problems
  constructor({
		position = createVector(10,10),
		speed = 2,       // speed is used to create a velocity vector
		velocity = () => createVector(      //velocity is a function as it changes each time. Set as function to allow change without subclassing.
	    random(-speed/1,speed),
			random(-speed/1,speed),
	  ),
		fillColor = color("red"),     // color not used as name as it creates a conflict with the p5 function
		size = 5,
		strength = 500,     // used to control particle life
		hueRange = 25,       // how far to vary from the specified colour
		lossFactor = 10,     // when outside the text area, lose this much strength
		lossRate = 1,        // basic loss rate
	}={}){

		// colour set within a range hueRange of input colour
		const h= hue(fillColor);

		this.fillColor= color(
			random(h-hueRange,h+hueRange)%360,
			random(20,saturation(fillColor)),
			random(50,50),
			0.2
		);
		this.position = position;
		this.velocity = velocity;   //velocity is speed + direction 
		this.size = size;
		this.strength = strength;
		this.speed = speed;
		this.lossFactor = lossFactor;
		this.lossRate = lossRate;
  }

	draw(){
		if (this.isAlive()){    // only draw if still have strength
			fill(this.fillColor);
			stroke(this.fillColor);
			circle(
				this.position.x,
				this.position.y,
				this.size,
			);
		}
	}

	isAlive(){
		return this.strength > 0;
	}

	updateStrength(){
		this.strength -= this.lossRate // pixelInTextArea(this.position.x,this.position.y) ? 
	}

	move(){
		if (this.isAlive()){
			this.updateStrength();
			this.position = this.position.add(this.velocity());    //update the position
		}	
	}

}

// === Tab: FollowingParticle ===
class FollowingParticle extends Particle {

	// I've used an object argument with defaults for the inputs
	// to avoid argument ordering problems
  constructor(props={}){
		super(props);		
		this.follows = props.follows || []; 

		this.velocity = () => {
			const pp = this.follows.map(p=>p.position);
			const [x,y] = ['x','y'].map(c=>this.position[c]-pp.reduce((acc,p)=>acc+(p[c]),0)/pp.length)
			const f= 0.05
			const ret =  createVector(-x * random(-f,f),-y * random(-f,f))
			stroke("black");
			return ret;
		}
  }
}

